//! Phase 6 v2.1 cross-domain transfer full-state verification.
//!
//! This test uses the real CLI binary, real RocksDB domain-pack storage,
//! deterministic synthetic bridge events generated by the command, CUDA
//! training, and real artifact files. It verifies success by reading the
//! persisted source-of-truth files after execution.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use serde_json::Value;

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn context_graph_bin() -> &'static str {
    env!("CARGO_BIN_EXE_context-graph")
}

fn run_cli(args: &[&str]) -> (bool, Value) {
    let output = Command::new(context_graph_bin())
        .args(args)
        .env("CONTEXT_GRAPH_ENV", "development")
        .output()
        .expect("execute context-graph binary");
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    let stderr = String::from_utf8(output.stderr).expect("CLI stderr is UTF-8");
    assert!(
        !stdout.trim().is_empty(),
        "CLI produced empty stdout; stderr={stderr}"
    );
    let value: Value = serde_json::from_str(&stdout)
        .unwrap_or_else(|err| panic!("stdout must be one JSON object: {err}\nstdout={stdout}"));
    (output.status.success(), value)
}

fn run_ok(args: &[&str]) -> Value {
    let (success, value) = run_cli(args);
    assert!(
        success,
        "command expected success but failed:\n{}",
        serde_json::to_string_pretty(&value).expect("pretty JSON")
    );
    assert_eq!(value["status"], "ok");
    value
}

fn run_err(args: &[&str]) -> Value {
    let (success, value) = run_cli(args);
    assert!(
        !success,
        "command expected failure but succeeded:\n{}",
        serde_json::to_string_pretty(&value).expect("pretty JSON")
    );
    assert_eq!(value["status"], "error");
    value
}

fn count(value: &Value, cf: &str) -> u64 {
    value["counts"][cf]
        .as_u64()
        .unwrap_or_else(|| panic!("missing count for {cf}: {value:#}"))
}

#[test]
fn dynamicjepa_cross_domain_transfer_phase6_v21_fsv() {
    let temp = tempfile::tempdir().expect("create temp dir");
    let root = repo_root();
    let db = temp.path().join("counter_to_grid_bridge_pack_rocksdb");
    let output_root = temp.path().join("cross_domain_transfer_out");
    let existing_output = temp.path().join("existing_output");
    let duplicate_seed_output = temp.path().join("duplicate_seed_out");
    let target_too_small_output = temp.path().join("target_too_small_out");
    fs::create_dir(&existing_output).expect("create existing output root");
    let bridge_pack = root.join("configs/dynamicjepa/domain_packs/counter_to_grid.v1.toml");

    let initial = run_ok(&[
        "dynamicjepa",
        "inspect-counts",
        "--db",
        db.to_str().expect("db utf8"),
        "--allow-missing",
        "--json",
    ]);
    println!(
        "PHASE6-XFER edge existing-root BEFORE: {}",
        existing_output.display()
    );
    assert_eq!(count(&initial, "dj_domain_packs"), 0);

    let registered = run_ok(&[
        "dynamicjepa",
        "register-domain",
        "--db",
        db.to_str().expect("db utf8"),
        "--file",
        bridge_pack.to_str().expect("bridge pack utf8"),
        "--json",
    ]);
    assert_eq!(
        registered["created_ids"]["domain_pack_id"],
        "counter_to_grid"
    );
    assert_eq!(
        registered["decoded_records"]["domain_pack"]["instrument_specs"]
            .as_array()
            .expect("instrument specs")
            .len(),
        2
    );

    let after_register = run_ok(&[
        "dynamicjepa",
        "inspect-counts",
        "--db",
        db.to_str().expect("db utf8"),
        "--json",
    ]);
    println!(
        "PHASE6-XFER bridge pack AFTER counts: {}",
        serde_json::to_string(&after_register["counts"]).expect("counts json")
    );
    assert_eq!(count(&after_register, "dj_domain_packs"), 1);
    assert_eq!(count(&after_register, "dj_instrument_registry"), 2);

    let inspected_domains = run_ok(&[
        "dynamicjepa",
        "inspect-cf",
        "--db",
        db.to_str().expect("db utf8"),
        "--cf",
        "dj_domain_packs",
        "--limit",
        "5",
        "--json",
    ]);
    assert!(
        !inspected_domains["decoded_records"]["rows"]
            .as_array()
            .expect("decoded rows")
            .is_empty(),
        "bridge pack must be physically readable from RocksDB"
    );

    let before_missing_output = Value::String(output_root.display().to_string());
    println!("PHASE6-XFER happy BEFORE output root: {before_missing_output}");
    let transferred = run_ok(&[
        "dynamicjepa",
        "cross-domain-transfer",
        "--output-root",
        output_root.to_str().expect("output utf8"),
        "--seeds",
        "42",
        "--source-events",
        "40",
        "--target-events",
        "24",
        "--bootstrap-iters",
        "100",
        "--train-epochs",
        "30",
        "--batch-size",
        "16",
        "--max-seconds-per-training",
        "60",
        "--stopping-target",
        "0.50",
        "--json",
    ]);
    assert_eq!(transferred["summary"]["phase1_passed_seeds"], 1);
    assert_eq!(transferred["summary"]["phase2_passed_seeds"], 1);

    let results_path = output_root.join("transfer_results.json");
    let table_path = output_root.join("paper_tables/table_cross_domain_transfer.csv");
    let plot_path = output_root.join("plots/cross_domain_transfer_box.svg");
    let results_text = fs::read_to_string(&results_path).expect("read transfer_results.json");
    let results: Value = serde_json::from_str(&results_text).expect("parse transfer results");
    println!(
        "PHASE6-XFER happy AFTER transfer_results summary: {}",
        serde_json::to_string(&serde_json::json!({
            "phase1_passed_seeds": results["phase1_passed_seeds"],
            "phase2_passed_seeds": results["phase2_passed_seeds"],
            "source_event_count": results["seeds"][0]["source_event_count"],
            "target_event_count": results["seeds"][0]["target_event_count"],
            "transfer_cosine": results["seeds"][0]["transfer_cosine"],
            "pairwise_effect": results["seeds"][0]["pairwise_effect"],
        }))
        .expect("summary json")
    );
    assert_eq!(results["phase1_passed_seeds"], 1);
    assert_eq!(results["seeds"][0]["source_event_count"], 40);
    assert_eq!(results["seeds"][0]["target_event_count"], 24);
    assert!(results["artifacts"]["seed_files"]
        .as_array()
        .expect("seed file manifest")
        .iter()
        .any(|entry| entry["path"]
            .as_str()
            .expect("path string")
            .ends_with("pairwise_on/model.safetensors")));
    assert!(
        !results["artifacts"]
            .as_object()
            .expect("artifact object")
            .contains_key("transfer_results_json"),
        "transfer_results.json must not embed its own hash"
    );

    let table_text = fs::read_to_string(&table_path).expect("read cross-domain table");
    println!("PHASE6-XFER happy AFTER table: {table_text}");
    assert!(table_text.contains("counter_world,gridworld_5x5"));
    let plot_text = fs::read_to_string(&plot_path).expect("read cross-domain plot");
    assert!(plot_text.starts_with("<svg "));
    assert!(output_root
        .join("bridge/seed_42/pairwise_on/model.safetensors")
        .is_file());

    let existing_err = run_err(&[
        "dynamicjepa",
        "cross-domain-transfer",
        "--output-root",
        existing_output.to_str().expect("existing output utf8"),
        "--seeds",
        "42",
        "--json",
    ]);
    println!("PHASE6-XFER edge existing-root AFTER: {existing_err}");
    assert_eq!(existing_err["error_code"], "VALIDATION");
    assert!(!existing_output.join("transfer_results.json").exists());

    let duplicate_seed_err = run_err(&[
        "dynamicjepa",
        "cross-domain-transfer",
        "--output-root",
        duplicate_seed_output
            .to_str()
            .expect("duplicate output utf8"),
        "--seeds",
        "42,42",
        "--json",
    ]);
    assert_eq!(duplicate_seed_err["error_code"], "VALIDATION");

    let target_too_small_err = run_err(&[
        "dynamicjepa",
        "cross-domain-transfer",
        "--output-root",
        target_too_small_output.to_str().expect("small output utf8"),
        "--target-events",
        "1",
        "--json",
    ]);
    assert_eq!(target_too_small_err["error_code"], "VALIDATION");
}
